package com.ngtintoreria.erp.laboratory;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="formula_versions",uniqueConstraints=@UniqueConstraint(columnNames={"formula_id","version_no"}))
public class FormulaVersion {
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="formula_id",nullable=false) private UUID formulaId; @Column(name="version_no",nullable=false) private int versionNo;
 @Column(nullable=false,length=20) private String status="DRAFT"; @Column(name="bath_ratio",precision=8,scale=3) private BigDecimal bathRatio; @Column(name="temperature_c",precision=8,scale=2) private BigDecimal temperatureC; @Column(name="time_minutes") private Integer timeMinutes; @Column(precision=6,scale=2) private BigDecimal ph; @Column(name="curve_text",columnDefinition="text") private String curveText;
 @Column(name="created_by",length=160) private String createdBy; @Column(name="created_at",nullable=false,updatable=false) private OffsetDateTime createdAt; @Column(name="released_at") private OffsetDateTime releasedAt;
 @PrePersist void pre(){createdAt=OffsetDateTime.now();}
 public UUID getId(){return id;} public UUID getFormulaId(){return formulaId;} public void setFormulaId(UUID v){formulaId=v;} public int getVersionNo(){return versionNo;} public void setVersionNo(int v){versionNo=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public BigDecimal getBathRatio(){return bathRatio;} public void setBathRatio(BigDecimal v){bathRatio=v;} public BigDecimal getTemperatureC(){return temperatureC;} public void setTemperatureC(BigDecimal v){temperatureC=v;} public Integer getTimeMinutes(){return timeMinutes;} public void setTimeMinutes(Integer v){timeMinutes=v;} public BigDecimal getPh(){return ph;} public void setPh(BigDecimal v){ph=v;} public String getCurveText(){return curveText;} public void setCurveText(String v){curveText=v;} public String getCreatedBy(){return createdBy;} public void setCreatedBy(String v){createdBy=v;} public OffsetDateTime getCreatedAt(){return createdAt;} public OffsetDateTime getReleasedAt(){return releasedAt;} public void setReleasedAt(OffsetDateTime v){releasedAt=v;}
}
